name: release

on:
  push:
    tags: ["v[0-9]*"]
  pull_request:
    branches: ["main"]
    # auto_merge_enabled arms the dry run on the release PR; see the gate job.
    types: [opened, synchronize, reopened, auto_merge_enabled]
  workflow_dispatch:
    inputs:
      force:
        description: "Force release even if one already exists"
        type: boolean
        default: false
      finish_draft_tag:
        description: "Attest/packslip/publish for a release tag (draft or published missing packslip). Example: v2026.9.2"
        type: string
        required: false
        default: ""

concurrency:
  group: release-${{ inputs.finish_draft_tag || github.ref_name }}
  # A dry run for a superseded release PR head can never satisfy auto-merge,
  # so stop it as soon as the next one starts. Tag runs are never cancelled.
  cancel-in-progress: ${{ github.event_name == 'pull_request' }}

env:
  CARGO_TERM_COLOR: always
  DRY_RUN: ${{ startsWith(github.ref, 'refs/tags/v') && '0' || '1' }}
  RUST_BACKTRACE: 1
  GITHUB_API_TOKEN: ${{ secrets.MISE_GH_TOKEN || secrets.GITHUB_TOKEN }}
  GITHUB_TOKEN: ${{ secrets.MISE_GH_TOKEN || secrets.GITHUB_TOKEN }}
  GH_TOKEN: ${{ secrets.MISE_GH_TOKEN || secrets.GITHUB_TOKEN }}

jobs:
  gate:
    # Decides what this run does. Tag pushes and manual dispatches always
    # build and publish. Pull requests only matter when they come from the
    # `release` branch of this repository, and even then the tarballs are only
    # built once auto-merge has been enabled on the release PR: every merge to
    # main force-pushes `release`, and building eight PGO tarballs for each of
    # those was the bulk of the Namespace bill. The `release` job below still
    # runs for an unarmed release PR so that the required check fails instead
    # of being skipped (GitHub treats a skipped required check as passed).
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions: {}
    outputs:
      release-run: ${{ steps.gate.outputs.release-run }}
      build: ${{ steps.gate.outputs.build }}
      finish-draft: ${{ steps.gate.outputs.finish-draft }}
      finish-draft-tag: ${{ steps.gate.outputs.finish-draft-tag }}
    steps:
      - id: gate
        env:
          RELEASE_RUN: ${{ github.event_name != 'pull_request' || (github.head_ref == 'release' && github.event.pull_request.head.repo.full_name == github.repository) }}
          ARMED: ${{ github.event_name != 'pull_request' || github.event.pull_request.auto_merge != null }}
          FINISH_DRAFT_TAG: ${{ inputs.finish_draft_tag }}
        run: |
          if [[ -n "$FINISH_DRAFT_TAG" ]]; then
            case "$FINISH_DRAFT_TAG" in
              v[0-9]*) ;;
              *)
                echo "::error::finish_draft_tag must look like v2026.9.2, got: $FINISH_DRAFT_TAG"
                exit 1
                ;;
            esac
            echo "release-run=false" >> "$GITHUB_OUTPUT"
            echo "build=false" >> "$GITHUB_OUTPUT"
            echo "finish-draft=true" >> "$GITHUB_OUTPUT"
            echo "finish-draft-tag=$FINISH_DRAFT_TAG" >> "$GITHUB_OUTPUT"
            echo "finish-draft tag=$FINISH_DRAFT_TAG (skipping build/release)"
            exit 0
          fi
          build=false
          if [ "$RELEASE_RUN" = true ] && [ "$ARMED" = true ]; then
            build=true
          fi
          echo "release-run=$RELEASE_RUN" >> "$GITHUB_OUTPUT"
          echo "build=$build" >> "$GITHUB_OUTPUT"
          echo "finish-draft=false" >> "$GITHUB_OUTPUT"
          echo "release-run=$RELEASE_RUN armed=$ARMED build=$build"
  build-tarball-linux:
    needs: [gate]
    if: needs.gate.outputs.build == 'true'
    name: build-tarball-${{matrix.name}}
    runs-on: ${{ github.event_name == 'pull_request' && (github.event.pull_request.head.repo.full_name != github.repository || (github.event.pull_request.user.login != 'jdx' && github.event.pull_request.user.login != 'mise-en-dev')) && 'ubuntu-latest' || 'namespace-profile-endev-linux-amd64-xlarge' }}
    # PGO and cross-built release tarballs can exceed 90 minutes on
    # loaded runners, especially once archive generation is included.
    timeout-minutes: 150
    env:
      MINIO_AWS_ACCESS_KEY_ID: ${{ secrets.MINIO_AWS_ACCESS_KEY_ID }}
      MINIO_AWS_SECRET_ACCESS_KEY: ${{ secrets.MINIO_AWS_SECRET_ACCESS_KEY }}
    strategy:
      fail-fast: false
      matrix:
        include:
          # pgo: the amd64 runner can execute x86_64 binaries, so those
          # targets build via scripts/pgo.bash (instrument -> train ->
          # rebuild with profile). bolt: apply post-link optimization to
          # the glibc x64 binary after PGO. arm targets can't run their
          # instrumented binaries here and stay plain serious builds.
          - name: linux-x64
            target: x86_64-unknown-linux-gnu
            pgo: 1
            bolt: 1
          - name: linux-x64-musl
            target: x86_64-unknown-linux-musl
            pgo: 1
          - name: linux-arm64
            target: aarch64-unknown-linux-gnu
          - name: linux-arm64-musl
            target: aarch64-unknown-linux-musl
          - name: linux-armv7
            target: armv7-unknown-linux-gnueabihf
          - name: linux-armv7-musl
            target: armv7-unknown-linux-musleabi
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
            // a file we never actually saw.
            Err(_) => Cached::Stale,
        },
        _ => Cached::Stale,
    }
}

